import { describe, it } from "vitest";

describe("quote", () => {
  it.todo("empty item list (newcomer) -> premium 5 G (only the processing fee)");
  it.todo("newcomer, plain steel sword enchantment 3 -> 100 base + 10 first insurance + 5 fee = 115 G");
  it.todo("newcomer, plain amulet -> 60 + 6 + 5 = 71 G");
  it.todo("newcomer, plain staff -> 80 + 8 + 5 = 93 G");
  it.todo("newcomer, plain potion -> 40 + 4 + 5 = 49 G");
  it.todo("newcomer, 2 runes -> base 50 G -> 50 + 5 + 5 = 60 G");
  it.todo("newcomer, 1 rune -> 25 + 2.5 + 5 = 32.5 -> rounded up in MHPCO's favor to 33 G");
  it.todo("newcomer, 1 moonstone -> 25 + 2.5 + 5 = 32.5 -> 33 G");
  it.todo("newcomer, 3 runes -> block base 60 G -> 60 + 6 + 5 = 71 G");
  it.todo("newcomer, 4 runes -> no block (exactly 3 required), base 100 G -> 115 G");
  it.todo("newcomer, 7 runes -> no block, base 175 G -> 197.5 -> rounded up to 198 G");
  it.todo("newcomer, 2 runes + 1 moonstone -> no block (different types), base 75 G -> 87.5 -> 88 G");
  it.todo("newcomer, 3 runes + 3 moonstones -> two blocks, base 120 G -> 137 G");
  it.todo("newcomer, cursed steel sword enchantment 3 -> 100 + 50 curse + 10 first = 160 + 5 = 165 G");
  it.todo("newcomer, cursed sword + plain amulet -> curse only on sword: 160 + 50 + 16 + 5 = 231 G");
  it.todo("newcomer, sword enchantment exactly 5 -> high-enchantment surcharge: 100 + 30 + 10 + 5 = 145 G");
  it.todo("newcomer, sword enchantment 4 -> no high-enchantment surcharge: 115 G");
  it.todo("newcomer, cursed sword enchantment 5 -> both surcharges: 100 + 50 + 30 + 10 + 5 = 195 G");
  it.todo("newcomer, cursed sword enchantment 4 -> only curse surcharge: 165 G");
  it.todo("newcomer, sword enchantment 5 + plain amulet -> surcharge only on sword: 160 + 30 + 16 + 5 = 211 G");
  it.todo("customer with exactly 2 years, plain sword -> loyalty discount: 100 - 20 + 10 + 5 = 95 G");
  it.todo("customer with 1 year, plain sword -> no loyalty discount: 115 G");
  it.todo("newcomer, second quote in scenario, plain sword -> follow-up discount: 100 + 10 - 15 + 5 = 100 G");
  it.todo("newcomer, third quote in scenario, plain sword -> follow-up discount still 15 %: 100 G");
  it.todo("3 years, second quote, cursed sword enchantment 7 -> 100 + 50 + 30 - 20 + 10 - 15 + 5 = 160 G");
  it.todo("quote with unknown item type 'broomstick' -> runScenario throws an Error (chosen contract: domain throws, CLI maps to non-zero exit)");
});

describe("claim", () => {
  it.todo("schema example: 5 years, silver amulet enchantment 2, fire damage 200 -> premium 59 G, payout 100 G, remainingCap 1100 G");
  it.todo("regular steel sword enchantment 3, damage 500 -> payout 400 G, remainingCap 1600 G");
  it.todo("rune, damage 200 -> payout 100 G, remainingCap 400 G");
  it.todo("steel sword enchantment 9, damage 1000 -> 50 % then deductible: payout 400 G");
  it.todo("dragon-material sword enchantment 9, damage 1000 -> 50 % rule wins: payout 400 G");
  it.todo("dragon-material sword enchantment 5, damage 800 -> full reimbursement: payout 700 G");
  it.todo("dragon-material sword enchantment exactly 8, damage 1000 -> high-enchantment clause applies: payout 400 G");
  it.todo("steel sword enchantment 9, damage 901 -> 350.5 -> rounded down in MHPCO's favor to 350 G");
  it.todo("sword + amulet, dragon attack damages sword 500 and amulet 300 -> deductible per item: payout 600 G, remainingCap 2600 G");
  it.todo("two swords insured, both damaged 500 each -> separate deductibles: payout 800 G, remainingCap 3200 G (cap 4000)");
  it.todo("cursed sword, damage 1500 -> cap based on unmodified value 2000: payout 1400 G, remainingCap 600 G");
  it.todo("sword + 3 runes (block), sword damage 500 -> insurance sum 1750, cap 3500: payout 400 G, remainingCap 3100 G");
  it.todo("sword, two successive claims of 1500 -> payouts 1400 G then 600 G, remainingCap 600 G then 0 G");
  it.todo("claim for an amulet when only a sword is insured -> runScenario throws an Error");
  it.todo("claim for an unknown item type -> runScenario throws an Error");
  it.todo("two sword damages but only one sword insured -> whole claim rejected: runScenario throws an Error");
  it.todo("damage amount -200 -> runScenario throws an Error");
});

