const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
function quote(step: QuoteStep, customer: Customer, isFollowUpContract: boolean): QuoteResult {
  step.items.forEach(assertInsurable);
  const policyBasePremium = policyBasePremiumOf(step.items);
  const unroundedPremium =
    policyBasePremium +
    riskSurchargesOf(step.items) +
    policyWideModifiersOn(policyBasePremium, customer, isFollowUpContract) +
    PROCESSING_FEE;
  return { premium: premiumRoundedInMHPCOsFavor(unroundedPremium) };
}

function isFollowUpContract(stepIndex: number): boolean {
  return stepIndex > 0;
}

export function runScenario(scenario: Scenario): { results: QuoteResult[] } {
  return {
    results: scenario.steps.map((step, stepIndex) => quote(step, scenario.customer, isFollowUpContract(stepIndex))),
  };
}

